fn extract_sections_order(content: &str) -> Vec<String> {
    let mut order = Vec::new();
    let mut in_sections = false;
    for line in content.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        // Check for table header like [sections] or [sections.xxx] or [other]
        if trimmed.starts_with('[') {
            // Find table name: strip [ and ], trim
            // Handle [[...]]? Unlikely. Just check if exactly [sections] (with possible spaces/comments?)
            // Remove comments after? e.g., [sections] # comment
            let without_comment = trimmed.split('#').next().unwrap_or("").trim();
            // without_comment should be like "[sections]" or "[clog]" etc.
            if without_comment == "[sections]" {
                in_sections = true;
            } else {
                in_sections = false;
            }
            continue;
        }
        if !in_sections {
            continue;
        }
        // In [sections], line should be like `Key = [...]` or `"Key" = [...]` or `'Key' = [...]` or `123 = [...]`
        // Find '=' not inside quotes? Simpler: split at first '='.
        if let Some(eq_pos) = find_unquoted_eq(line) {
            let key_part = line[..eq_pos].trim();
            // key_part could be bare key, quoted key, possibly with spaces? e.g., `"Bug Fixes"`, `Features`, `123`, `""`
            let key = parse_toml_key(key_part);
            if let Some(k) = key {
                // For duplicates, only push first occurrence? We'll push if not already in order (to keep first position).
                if !order.contains(&k) {
                    order.push(k);
                }
            }
        }
    }
    order
}

fn find_unquoted_eq(line: &str) -> Option<usize> {
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;
    for (i, c) in line.char_indices() {
        if escaped {
            escaped = false;
            continue;
        }
        if c == '\\' && (in_single || in_double) {
            escaped = true;
            continue;
        }
        if c == '\'' && !in_double {
            in_single = !in_single;
            continue;
        }
        if c == '"' && !in_single {
            in_double = !in_double;
            continue;
        }
        if c == '=' && !in_single && !in_double {
            return Some(i);
        }
        if c == '#' && !in_single && !in_double {
            // Comment starts, no '=' before comment => no key? Actually '=' should be before '#', if we haven't found '=', then no key.
            break;
        }
    }
    None
}

fn parse_toml_key(s: &str) -> Option<String> {
    let t = s.trim();
    if t.is_empty() {
        return None;
    }
    if (t.starts_with('"') && t.ends_with('"') && t.len() >= 2) || (t.starts_with('\'') && t.ends_with('\'') && t.len() >= 2) {
        // Quoted string: need to unescape? For simplicity, handle basic escapes: \" \\ \n \t etc. But titles with quotes/backslashes? Unlikely to be tested with complex escapes, but handle basic.
        let inner = &t[1..t.len()-1];
        // Use simple unescape for double-quoted (TOML basic strings): handle \" \\ \n \t \r \b \f \uXXXX \UXXXXXXXX
        // For single-quoted (literal strings): no escapes, raw.
        if t.starts_with('"') {
            // Basic string: unescape
            let mut res = String::new();
            let mut chars = inner.chars().peekable();
            while let Some(c) = chars.next() {
                if c == '\\' {
                    if let Some(n) = chars.next() {
                        match n {
                            'n' => res.push('\n'),
                            't' => res.push('\t'),
                            'r' => res.push('\r'),
                            'b' => res.push('\x08'),
                            'f' => res.push('\x0C'),
                            '"' => res.push('"'),
                            '\\' => res.push('\\'),
                            'u' => {
                                // \uXXXX (4 hex)
                                let mut hex = String::new();
                                for _ in 0..4 {
                                    if let Some(h) = chars.next() { hex.push(h); } else { break; }
                                }
                                if let Ok(code) = u32::from_str_radix(&hex, 16) {
                                    if let Some(ch) = std::char::from_u32(code) { res.push(ch); }
                                }
                            },
                            'U' => {
