    let cli_to: String = matches.get_one::<String>("to").cloned().unwrap_or("HEAD".to_string());
    let cli_outfile: Option<String> = matches.get_one::<String>("outfile").cloned();
    let cli_config: String = matches.get_one::<String>("config").cloned().unwrap_or(".clog.toml".to_string());
    let cli_infile: Option<String> = matches.get_one::<String>("infile").cloned();
    let cli_setversion: Option<String> = matches.get_one::<String>("setversion").cloned();
    let cli_from_latest_tag = matches.get_flag("from-latest-tag");
    let cli_link_style: String = matches.get_one::<String>("link-style").cloned().unwrap_or("github".to_string());
    let cli_changelog: Option<String> = matches.get_one::<String>("changelog").cloned();

    // Handle version increment flags without setversion => error
    if (cli_major || cli_minor || cli_patch) && cli_setversion.is_none() {
        err_parse_version();
    }
    let version_opt: Option<String> = cli_setversion.clone();
