        (cli_ch.clone(), None)
    } else if cli_out.is_some() {
        let infile = if cli_in.is_some() { cli_in.clone() } else { cfg_in.clone() };
        (cli_out.clone(), infile)
    } else if cli_in.is_some() {
        let out = if cfg_ch.is_some() { cfg_ch.clone() } else if cfg_out.is_some() { cfg_out.clone() } else { None };
