        if cfg_ch.is_some() {
            (cfg_ch.clone(), None)
        } else if cfg_out.is_some() {
            (cfg_out.clone(), cfg_in.clone())
        } else if cfg_in.is_some() {
            (None, cfg_in.clone())
        } else {
            (None, None)
        }
    };

