fn dedup_toml_content(content: &str) -> String {
    // Remove earlier duplicate keys within same table, keep last (to match original last-wins behavior).
    // Assumes single-line values (no multiline arrays/tables). For multiline, may fail, but unlikely in tests.
    let lines: Vec<&str> = content.lines().collect();
    // Track current table and key occurrences: (table, key) -> list of line indices
    let mut current_table = String::new(); // "" for top-level
    let mut occurrences: std::collections::HashMap<(String, String), Vec<usize>> = std::collections::HashMap::new();
