    for (_, indices) in occurrences {
        if indices.len() > 1 {
            for &i in &indices[..indices.len()-1] {
                to_remove.insert(i);
            }
        }
    }
    // Rebuild content without removed lines
    let mut out = String::new();
    for (idx, line) in lines.iter().enumerate() {
        if to_remove.contains(&idx) {
            continue;
        }
        out.push_str(line);
        out.push_str("\\n");
    }
    out
}

